import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"start/quickstart.md","filePath":"start/quickstart.md"}'),n={name:"start/quickstart.md"};function d(p,s,l,o,h,c){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>这一页带你从零开始：安装 nek、连接一个模型、完成第一个任务，然后学会续接会话。整个过程大约十分钟。</p><h2 id="_1-安装" tabindex="-1">1. 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to &quot;1. 安装&quot;">​</a></h2><p>还没装的话，先按 <a href="/nekcode/start/install">安装</a> 运行一键安装脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/deepdarkpaw/nekcode/nek/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw.githubusercontent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deepdarkpaw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nekcode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nek</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scripts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>打开新终端，确认 <code>nek --version</code> 能输出版本号。</p><h2 id="_2-在项目目录里启动" tabindex="-1">2. 在项目目录里启动 <a class="header-anchor" href="#_2-在项目目录里启动" aria-label="Permalink to &quot;2. 在项目目录里启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span></span></code></pre></div><p>启动目录很重要，nek 用它来：</p><ul><li>查找项目文件、项目指令（<code>AGENTS.md</code>）和项目配置（<code>.nek/</code>）；</li><li>作为工具的默认工作目录；</li><li>给会话分组（<code>nek -c</code> 续接的是<strong>这个目录</strong>最近的会话）。</li></ul><p>如果项目里有 <code>.nek/settings.json</code>、<code>.nek/extensions/</code> 这类会执行或改变行为的配置，nek 会先问你是否信任这个项目，见 <a href="/nekcode/guide/security#project-trust">项目信任</a>。</p><p>界面从上到下分为三部分：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 对话记录：你的消息、模型回复、工具调用和结果       │  ← PageUp/PageDown 或鼠标滚轮滚动</span></span>
<span class="line"><span>│ ...                                          │</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [Todo 列表 / 运行中的子代理]                    │  ← 有内容时才出现</span></span>
<span class="line"><span>│ &gt; 在这里输入                                   │  ← 输入框，边框颜色表示思考等级或 Plan 模式</span></span>
<span class="line"><span>├──────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 当前目录 · 用量与费用 · 上下文进度条 · 模型         │  ← 状态栏（footer）</span></span>
<span class="line"><span>└──────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="connect-model" tabindex="-1">3. 连接模型 <a class="header-anchor" href="#connect-model" aria-label="Permalink to &quot;3. 连接模型 {#connect-model}&quot;">​</a></h2><p><strong>模型</strong>负责生成回复，**服务商（provider）**是你访问这个模型的服务或账号。</p><p>在 nek 的输入框里输入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p>选择服务商，然后按提示操作：</p><ul><li>有订阅（例如 Claude Pro/Max、ChatGPT Plus/Pro、GitHub Copilot）的服务商会打开浏览器登录；</li><li>其他服务商让你粘贴 API key。</li></ul><p>凭据保存在 <code>~/.nek/agent/auth.json</code>。登录后用 <code>/model</code> 搜索并选择模型，在模型上按 <code>Ctrl+S</code> 可以把它保存为新会话的默认模型。</p><div class="tip custom-block"><p class="custom-block-title">用中转地址或自建服务？</p><p>OpenAI 兼容、Anthropic 兼容的中转地址，以及 Ollama、vLLM、LM Studio 等本地服务，写在 <code>~/.nek/agent/models.json</code> 里，见 <a href="/nekcode/guide/models#compatible-endpoint">选择模型</a>。</p></div><p>不想把 key 存到磁盘？启动前设置环境变量也行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span></span></code></pre></div><p>各服务商的变量名见 <a href="/nekcode/reference/providers">服务商认证</a>。</p><h2 id="_4-交给它一个任务" tabindex="-1">4. 交给它一个任务 <a class="header-anchor" href="#_4-交给它一个任务" aria-label="Permalink to &quot;4. 交给它一个任务&quot;">​</a></h2><p>直接用自然语言描述你要做的事，按 <code>Enter</code> 发送。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解释一下这个仓库的目录结构，以及怎么运行它的测试。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把 @src/config.ts 里的硬编码超时改成从环境变量读取，并补上单元测试。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对比 @old.csv 和 @new.csv，总结重要的变化。</span></span></code></pre></div><p>输入 <code>@</code> 可以模糊搜索文件并插入路径。nek 工作时，你会看到它每一次读文件、搜索、执行命令和修改文件的过程。它<strong>不会</strong>在每次调用工具前征求同意，所以：</p><ul><li>重要的工作请先提交到 git 或做好备份；</li><li>完成后检查它的回复和改动（<code>git diff</code>）；</li><li>不可信或无人值守的任务放进容器，见 <a href="/nekcode/guide/security">安全使用</a>。</li></ul><p>工作过程中你可以随时插话：直接输入并按 <code>Enter</code> 会在当前步骤结束后插入你的消息；按 <code>Escape</code> 中止。详见 <a href="/nekcode/guide/usage#steer">终端界面与输入</a>。</p><h2 id="_5-复杂任务-先出计划" tabindex="-1">5. 复杂任务：先出计划 <a class="header-anchor" href="#_5-复杂任务-先出计划" aria-label="Permalink to &quot;5. 复杂任务：先出计划&quot;">​</a></h2><p>需求比较大、或者你想先看方案再动手时，用 Plan 模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plan 给登录接口加上限流，按 IP 每分钟 20 次</span></span></code></pre></div><p>nek 会只读地调研代码、在必要时向你提问，然后写出一份计划。你审阅后选择 <strong>Implement</strong>，它切回 Agent 模式按计划实施。<code>Alt+M</code> 可以随时在两种模式间切换。详见 <a href="/nekcode/guide/plan-mode">Plan 模式</a>。</p><h2 id="_6-下次接着做" tabindex="-1">6. 下次接着做 <a class="header-anchor" href="#_6-下次接着做" aria-label="Permalink to &quot;6. 下次接着做&quot;">​</a></h2><p>nek 会自动保存会话。退出后（<code>Ctrl+C</code> 两次，或空输入框时按 <code>Ctrl+D</code>），在同一个目录里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 继续这个目录最近的会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 从列表里选一个会话</span></span></code></pre></div><p>在 nek 里用 <code>/resume</code> 切换会话，<code>/new</code> 开新会话。即使 nek 是被强制杀掉的，<code>nek -c</code> 也会把中断的那一轮接着跑完，见 <a href="/nekcode/reference/durable-sessions">Durable 会话</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做的事</th><th>去看</th></tr></thead><tbody><tr><td>熟悉输入框、快捷键、排队消息</td><td><a href="/nekcode/guide/usage">终端界面与输入</a></td></tr><tr><td>给项目写长期有效的指令</td><td><a href="/nekcode/customize/context-files">项目指令（AGENTS.md）</a></td></tr><tr><td>了解每个工具能做什么</td><td><a href="/nekcode/guide/tools">内置工具</a></td></tr><tr><td>让多个子任务并行</td><td><a href="/nekcode/guide/subagents">子代理</a></td></tr><tr><td>接入 MCP 服务器</td><td><a href="/nekcode/guide/mcp">MCP 服务器</a></td></tr><tr><td>在脚本里调用 nek</td><td><a href="/nekcode/develop/cli-integration">脚本与程序集成</a></td></tr></tbody></table><h3 id="选择合适的定制方式" tabindex="-1">选择合适的定制方式 <a class="header-anchor" href="#选择合适的定制方式" aria-label="Permalink to &quot;选择合适的定制方式&quot;">​</a></h3><p>从能满足需求的最简单方式开始：</p><table tabindex="0"><thead><tr><th>需求</th><th>用</th></tr></thead><tbody><tr><td>给某个目录写长期有效的指令</td><td><a href="/nekcode/customize/context-files"><code>AGENTS.md</code></a></td></tr><tr><td>把常用提示词做成 <code>/</code> 命令</td><td><a href="/nekcode/customize/prompt-templates">提示词模板</a></td></tr><tr><td>打包一套专项说明和配套脚本</td><td><a href="/nekcode/customize/skills">Skills</a></td></tr><tr><td>定义自己的子代理类型</td><td><a href="/nekcode/guide/subagents#custom-types">自定义子代理</a></td></tr><tr><td>添加可执行的工具、命令或事件处理</td><td><a href="/nekcode/develop/extensions">扩展</a></td></tr><tr><td>接入一个 nek 不支持的模型服务</td><td><a href="/nekcode/develop/custom-provider">自定义服务商</a></td></tr></tbody></table>`,46)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
